#!/usr/bin/env python3
"""Supplementary Tables S1–S5 generated from the manifest and analysis_v2/results (rule 0.4-1; never hand-edited).
Output: manuscript/revised_v2/supplementary_tables/TableS{1a,1b,2,3a..3f,4,4b,5}_*.tsv (one TSV per sheet) + a README listing the
source file of every sheet. Captions: manuscript/revised_v2/supplementary_table_captions.md."""
import os, shutil
import numpy as np, pandas as pd
PROJ="/usr/local/jupyter/FVB_bias"; RES=f"{PROJ}/analysis_v2/results"; NC=f"{RES}/negative_control"; OUT=f"{PROJ}/manuscript/revised_v2/supplementary_tables"
os.makedirs(OUT, exist_ok=True); src=[]
def w(name, df, source):
    p=f"{OUT}/{name}.tsv"; df.to_csv(p, sep="\t", index=False); src.append((name, source, len(df))); print(f"{name}: {len(df)} rows")
# S1
man=pd.read_csv(f"{PROJ}/revision_v2/manifest/manifest.tsv", sep="\t", dtype=str)
w("TableS1a_manifest", man[["sample_id","GSE","GSM","BioSample","SRR","strain","tissue","diet","sex","age","library_layout","read_length","include","include_reason","role","design_main","design_sensitivity","n_technical_runs","read_count_total"]], "revision_v2/manifest/manifest.tsv")
qc=pd.read_csv(f"{RES}/qc/sample_identity_verification.tsv", sep="\t", dtype=str); w("TableS1b_identity_verification", qc, "analysis_v2/results/qc/sample_identity_verification.tsv")
# S2
cat=pd.read_csv(f"{RES}/catalog/catalog.primary.tsv", sep="\t"); meta=pd.read_csv(f"{RES}/gene_meta.tsv", sep="\t", index_col=0)
cw=pd.read_csv(f"{RES}/catalog/catalog.water.tsv", sep="\t"); cm=pd.read_csv(f"{RES}/sensitivity_matched/catalog.matched.tsv", sep="\t")
py=pd.read_csv(f"{NC}/pyvt_reference_swap_per_gene.tsv", sep="\t", index_col=0)
cat["chrom"]=cat.gene_id.map(meta.chrom); cat["start"]=cat.gene_id.map(meta.start); cat["end"]=cat.gene_id.map(meta.end)
cat["in_control_only_catalog"]=np.where(cat.gene_id.isin(cw.gene_id),"Y","N"); cat["in_matched_reference_catalog"]=np.where(cat.gene_id.isin(cm.gene_id),"Y","N")
cat["pyvt_median_reference_swap"]=cat.gene_id.map(py.median(axis=1))
cols=["gene_id","gene_name","biotype","chrom","start","end","n_tissues","n_tissues_tested","mean_bias","tissues","adipose","hypothalamus","liver","skin","snp_density_per_kb","mean_bias_multi","delta_multi_minus_unique","residual_fraction","mechanism_class","in_control_only_catalog","in_matched_reference_catalog","pyvt_median_reference_swap"]
w("TableS2_catalog", cat[cols].sort_values("mean_bias",ascending=False), "analysis_v2/results/catalog/catalog.primary.tsv (+ catalog.water.tsv, sensitivity_matched/catalog.matched.tsv, negative_control/pyvt_reference_swap_per_gene.tsv, gene_meta.tsv)")
# S3
w("TableS3a_sensitivity_primary", pd.read_csv(f"{RES}/catalog/catalog_sensitivity.primary.tsv", sep="\t"), "analysis_v2/results/catalog/catalog_sensitivity.primary.tsv")
w("TableS3b_sensitivity_control_only", pd.read_csv(f"{RES}/catalog/catalog_sensitivity.water.tsv", sep="\t"), "analysis_v2/results/catalog/catalog_sensitivity.water.tsv")
sm=pd.read_csv(f"{RES}/sensitivity_matched/summary.tsv", sep="\t"); rows=[]
for _,r in sm[sm["item"].str.startswith("grid")].iterrows():
    k=r["item"]; thr=float(k.split("thr=")[1].split(" ")[0]); mt=int(k.split("min_tissues=")[1].split(":")[0]); a,b,c=[int(x) for x in str(r["value"]).split(" / ")]
    rows.append({"threshold":thr,"min_tissues":mt,"n_primary":a,"n_matched":b,"n_both":c})
w("TableS3c_sensitivity_matched_reference", pd.DataFrame(rows), "analysis_v2/results/sensitivity_matched/summary.tsv")
rs=pd.read_csv(f"{NC}/reference_swap_summary.tsv", sep="\t"); strata=pd.read_csv(f"{NC}/catalog_swap_by_chrom_stratum.tsv", sep="\t").set_index("sample_id")
rs.insert(3,"group",rs.sample_id.map(strata["group"])); w("TableS3d_negative_control_per_animal", rs, "analysis_v2/results/negative_control/reference_swap_summary.tsv (+ catalog_swap_by_chrom_stratum.tsv for the group label)")
w("TableS3e_negative_control_heldout", pd.read_csv(f"{NC}/heldout_catalog_swap.tsv", sep="\t"), "analysis_v2/results/negative_control/heldout_catalog_swap.tsv")
w("TableS3f_pyvt_residual_segments", pd.read_csv(f"{NC}/pyvt_fullsite_chr3_10_16.per_animal.tsv", sep="\t"), "analysis_v2/results/negative_control/pyvt_fullsite_chr3_10_16.per_animal.tsv")
# S4
w("TableS4_alignment_stats_per_animal_arm", pd.read_csv(f"{RES}/qc/mapping_stats_per_sample.tsv", sep="\t"), "analysis_v2/results/qc/mapping_stats_per_sample.tsv")
w("TableS4b_wasp_attrition_by_group", pd.read_csv(f"{PROJ}/manuscript/revised_v2/generated/wasp_attrition_by_group.tsv", sep="\t"), "manuscript/revised_v2/generated/wasp_attrition_by_group.tsv (results_numbers.py)")
# S5
sv=pd.read_csv(f"{RES}/survey/survey_of_practice_v2.tsv", sep="\t", dtype=str); w("TableS5_survey_of_practice", sv, "analysis_v2/results/survey/survey_of_practice_v2.tsv")
with open(f"{OUT}/README.md","w") as o:
    o.write("# Supplementary tables (generated by revision_v2/scripts/build_supplementary_tables.py)\n\n| sheet | source | rows |\n|---|---|---|\n")
    for n,s,k in src: o.write(f"| {n} | `{s}` | {k} |\n")
print("done")
